-- ============================================================================
-- Ива — ввоз справочника прокатов (этап П2)
--
-- Файл собран автоматически (tools/build_directory_import.py) из tools/real_bases.csv.
-- Строк к ввозу: 115. Источники: открытые справочники (поле source у каждой строки).
--
-- Как запускать: Supabase -> SQL Editor -> New query -> вставить весь файл -> Run.
-- Повторный запуск безопасен: строки обновляются, дубли не создаются,
-- а статусы проверки (status, checked_at) НЕ затираются.
-- ============================================================================

begin;

on conflict (phone, address) do update set
  city         = excluded.city,
  city_slug    = excluded.city_slug,
  name         = excluded.name,
  source       = excluded.source,
  has_whatsapp = excluded.has_whatsapp,
  updated_at   = now();

commit;

-- Итог: что получилось (пришлите эту табличку обратно — по ней видно результат)
select
  count(*)                                        as "всего строк",
  count(*) filter (where city_slug is null)       as "городов нет в списке сайта",
  count(*) filter (where status = 'new')          as "ждут проверки",
  count(distinct city)                            as "городов",
  count(distinct phone)                           as "телефонов"
from public.directory_landlords;
